-- A pre-migration (push-ups only) Spotter database: schema + a slice of sample data.
BEGIN TRANSACTION;
CREATE TABLE challenges (
	id INTEGER NOT NULL, 
	group_id INTEGER NOT NULL, 
	title VARCHAR(80) NOT NULL, 
	description TEXT NOT NULL, 
	exercise VARCHAR(20) NOT NULL, 
	goal_reps INTEGER NOT NULL, 
	min_sessions_per_member INTEGER NOT NULL, 
	starts_at DATETIME NOT NULL, 
	ends_at DATETIME NOT NULL, 
	difficulty VARCHAR(10) NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	ai_model VARCHAR(60), 
	rationale TEXT, 
	created_by_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(group_id) REFERENCES groups (id) ON DELETE CASCADE, 
	FOREIGN KEY(created_by_id) REFERENCES users (id)
);
INSERT INTO "challenges" VALUES(1,1,'1,000 together this week','Every valid push-up from every member counts. Two sessions each matters more than one huge set.','pushup',1000,2,'2026-11-05 12:04:12.393127','2026-11-12 12:04:12.393127','moderate','rules',NULL,'Sample challenge created by the seed script.',1,'2026-11-08 12:04:12.448048');
CREATE TABLE group_members (
	id INTEGER NOT NULL, 
	group_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	role VARCHAR(10) NOT NULL, 
	joined_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (group_id, user_id), 
	FOREIGN KEY(group_id) REFERENCES groups (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
INSERT INTO "group_members" VALUES(1,1,1,'owner','2026-11-08 12:04:12.427804');
