INSERT INTO "group_members" VALUES(5,1,5,'member','2026-11-08 12:04:12.427810');
CREATE TABLE groups (
	id INTEGER NOT NULL, 
	name VARCHAR(60) NOT NULL, 
	description VARCHAR(280), 
	invite_code VARCHAR(12) NOT NULL, 
	created_by_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(created_by_id) REFERENCES users (id)
);
INSERT INTO "groups" VALUES(1,'Panorama Push Club','Lunchtime push-ups, rain or shine.','DEMO42',1,'2026-11-08 12:04:12.391442');
CREATE TABLE insights (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	week_start DATE NOT NULL, 
	payload JSON NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	ai_model VARCHAR(60), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (user_id, week_start), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
INSERT INTO "insights" VALUES(1,1,'2026-11-02','{"headline": "h", "summary": "s", "highlights": ["a"], "next_steps": ["b"]}','rules',NULL,'2026-11-07 10:00:00');
CREATE TABLE reactions (
	id INTEGER NOT NULL, 
	workout_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	kind VARCHAR(12) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (workout_id, user_id, kind), 
	FOREIGN KEY(workout_id) REFERENCES workouts (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
