CREATE TABLE users (
	id INTEGER NOT NULL, 
	auth0_sub VARCHAR(255) NOT NULL, 
	username VARCHAR(32) NOT NULL, 
	display_name VARCHAR(80) NOT NULL, 
	avatar_url VARCHAR(1024), 
	email VARCHAR(320), 
	is_demo BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	last_seen_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
