CREATE TABLE workouts (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	exercise VARCHAR(20) NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	visibility VARCHAR(10) NOT NULL, 
	started_at DATETIME NOT NULL, 
	duration_ms INTEGER NOT NULL, 
	target_reps INTEGER NOT NULL, 
	valid_reps INTEGER NOT NULL, 
	attempted_reps INTEGER NOT NULL, 
	form_score FLOAT NOT NULL, 
	rep_score FLOAT NOT NULL, 
	final_score FLOAT NOT NULL, 
	consistency FLOAT NOT NULL, 
	confidence FLOAT NOT NULL, 
	scoring_version INTEGER NOT NULL, 
	component_averages JSON NOT NULL, 
	rep_metrics JSON NOT NULL, 
	note VARCHAR(280), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
